# Crop real page captures into clippings (crops only, nothing altered) + highlight boxes (clip px). Writes _shared/clips.js
import json, os
from PIL import Image
D = os.path.abspath(os.path.join(os.path.dirname(__file__), '..')); S = os.path.join(D, '_src/caps'); O = os.path.join(D, '_src/clips'); os.makedirs(O, exist_ok=True)
def clip(name, img, box, hls, source, url):
    x0, y0, x1, y1 = box; Image.open(os.path.join(S, img)).convert('RGB').crop(box).save(os.path.join(O, name + '.png'))
    return name, {'w': x1 - x0, 'h': y1 - y0, 'hl': [[a - x0, b - y0, c, d] for a, b, c, d in hls], 'source': source, 'url': url}
out = dict([
  clip('rfc-first', 'rfc9110__the-first-digit-of-the-s.png', (110, 590, 1230, 1060), [[124, 778, 610, 34]], 'RFC 9110 · HTTP Semantics · §15', 'https://www.rfc-editor.org/rfc/rfc9110.html#name-status-codes'),
  clip('gh-404', 'github__to-avoid-confirming-the-.png', (405, 605, 1515, 820), [[600, 780, 735, 34]], 'GitHub Docs · Troubleshooting the REST API', 'https://docs.github.com/en/rest/using-the-rest-api/troubleshooting-the-rest-api'),
  clip('google-4xx', 'google__are-treated-the-same.png', (820, 768, 1580, 1150), [[1060, 776, 460, 34], [828, 1046, 196, 34], [828, 1113, 134, 34]], 'Google Search Central · HTTP status codes', 'https://developers.google.com/search/docs/crawling-indexing/http-network-errors'),
  clip('google-line', 'google__are-treated-the-same.png', (1052, 770, 1528, 812), [[1060, 776, 460, 34]], 'Google Search Central · HTTP status codes', 'https://developers.google.com/search/docs/crawling-indexing/http-network-errors'),
  clip('gh-line', 'github__to-avoid-confirming-the-.png', (405, 738, 1515, 818), [[600, 780, 735, 34]], 'GitHub Docs · Troubleshooting the REST API', 'https://docs.github.com/en/rest/using-the-rest-api/troubleshooting-the-rest-api'),
])
json.dump(out, open(os.path.join(O, 'clips.json'), 'w'), indent=1)
open(os.path.join(D, '_shared', 'clips.js'), 'w').write('/* generated by _tools/clips.py: real page clippings (crops only) + highlight boxes in clip px */\nconst CLIPS = ' + json.dumps(out) + ';\n')
print(list(out))
